document.addEventListener('keydown', (event) => {
  if (event.key === 'p' || event.key === 'P') {
    console.log('Pause key pressed');
  }
});

let isPaused = false;

function togglePause() {
  isPaused = !isPaused;
  console.log(`Game is ${isPaused ? 'paused' : 'running'}`);
}

